#include <iostream>
#include <vector>
#include <ranges>
#include <numeric>

int main() {
    using namespace std;
    unsigned N;
    cin >> N;
    vector<unsigned> P(N);
    for (auto&& p : P) {
        cin >> p;
        --p;
    }
    vector<unsigned> ans(N);
    for (const auto i : views::iota(0U, N)) if (!ans[i]) {
        auto p{i};
        unsigned count{};
        do {
            ++count;
            p = P[p];
        } while (p != i); // サイクルを検出して
        do {
            ans[p] = count; // その頂点が属するサイクルの大きさを記録する
            p = P[p];
        } while (p != i);
    }
    cout << (reduce(begin(ans), end(ans), 0UL) - N) / 2 << endl;
    return 0;
}
